(() => {
  const q=s=>document.querySelector(s),qa=s=>[...document.querySelectorAll(s)];
  const labels={home:'Network lab',lab:'Phase measurements',results:'Reported findings',dataset:'Dataset explorer',gallery:'Graph library',downloads:'Research downloads',research:'The paper',framework:'Framework & methodology',workloads:'Workload evidence',cinema:'Traffic cinema'};
  const routes=[...document.querySelectorAll('main>section')];
  document.documentElement.classList.add('route-ready');
  const bar=document.createElement('div');bar.className='route-bar';bar.innerHTML='<a href="#home">← Back to the network lab</a><span id="route-name"></span><a href="#downloads">All downloads ↓</a>';q('main').before(bar);
  let activeRoute='home',tourTimer=null,cycleTimer=null,liveScenario=0,inspectIndex=-1,renderNodes=[],pointer={x:0,y:0};
  function route(){const id=location.hash.slice(1)||'home';activeRoute=labels[id]?id:'home';routes.forEach(s=>{const active=s.id===activeRoute;s.classList.toggle('route-active',active);s.setAttribute('aria-hidden',!active);});bar.hidden=activeRoute==='home';q('#route-name').textContent=labels[activeRoute].toUpperCase();qa('header nav a').forEach(a=>{const current=a.hash==='#'+activeRoute;if(current)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current');});q('nav').classList.remove('open');q('#menu').setAttribute('aria-expanded','false');q('#menu').setAttribute('aria-label','Open navigation');document.title=labels[activeRoute]+' | Beyond Static Traffic';window.scrollTo({top:0,behavior:'instant'});if(activeRoute!=='home'){stopCycle();stopTour();}if(activeRoute!=='cinema')q('#research-film').pause();requestAnimationFrame(()=>{resizeCanvas();window.scrollTo({top:0,behavior:"instant"});});}
  addEventListener('hashchange',route);
  const captions=['CONTINUOUS UDP + ICMP','AUTHORIZED TRAFFIC BURST','BOUNDED TCP RECONNAISSANCE','CONTROLLED UDP INCREASE','CONNECT / CLOSE / REPEAT','SPARSE SERVICE PROBES'];
  const oldScenario=setScenario;
  setScenario=function(i){oldScenario(i);liveScenario=i;qa('[data-live-scenario]').forEach(b=>{const active=Number(b.dataset.liveScenario)===i;b.classList.toggle('selected',active);b.setAttribute('aria-pressed',active);});q('#live-title').textContent=scenarios[i][2];q('#live-description').textContent=scenarios[i][3];q('#live-caption').textContent=captions[i];};
  const oldPhase=setPhase;
  setPhase=function(i){oldPhase(i);qa('[data-live-phase]').forEach(b=>{const active=Number(b.dataset.livePhase)===i;b.classList.toggle('selected',active);b.setAttribute('aria-pressed',active);});q('#phase-slider').value=i;q('#phase-selection').textContent=['Stable','Constrained','Recovery'][i]+' · '+(i+1)+' of 3';q('#phase-slider').setAttribute('aria-valuetext',['Stable','Constrained','Recovery'][i]);q('#phase-progress').style.width=((i+1)/3*100)+'%';q('#live-rtt').textContent=phases[i].rtt.toFixed(4);q('#live-goodput').textContent=phases[i].goodput.toFixed(4);q('#rtt-point').setAttribute('cx',[0,90,180][i]);q('#rtt-point').setAttribute('cy',[30,3,30][i]);q('#goodput-point').setAttribute('cx',[0,90,180][i]);q('#goodput-point').setAttribute('cy',[4,31,4][i]);};
  qa('[data-live-scenario]').forEach(b=>b.addEventListener('click',()=>{stopTour();setScenario(Number(b.dataset.liveScenario));}));
  qa('[data-live-phase]').forEach(b=>b.addEventListener('click',()=>{stopTour();stopCycle();setPhase(Number(b.dataset.livePhase));}));
  q('#phase-slider').addEventListener('input',e=>{stopTour();stopCycle();setPhase(Number(e.target.value));});
  q('#open-context').addEventListener('click',()=>location.hash='workloads');
  q('#live-topology').addEventListener('click',()=>{topology=topology==='star'?'line':'star';drawTopology();q('#live-topology').textContent=(topology==='star'?'Star':'Line')+' topology ⇄';inspectIndex=-1;q('#node-inspector strong').textContent='Topology changed. Click a node to explore its role.';});
  const oldMotion=setMotion;setMotion=function(v){oldMotion(v);q('#stage-pause').textContent=v?'▶ Resume':'Ⅱ Pause';q('#stage-pause').setAttribute('aria-pressed',v);if(v){stopCycle();stopTour();}};
  q('#stage-pause').addEventListener('click',()=>setMotion(!paused));
  function stopCycle(){clearInterval(cycleTimer);cycleTimer=null;q('#phase-cycle').textContent='▶ Play phase cycle';q('#phase-cycle').setAttribute('aria-pressed','false');}
  q('#phase-cycle').addEventListener('click',()=>{stopTour();if(cycleTimer){stopCycle();return;}if(paused)setMotion(false);q('#phase-cycle').textContent='Ⅱ Pause cycle';q('#phase-cycle').setAttribute('aria-pressed','true');setPhase((phase+1)%3);cycleTimer=setInterval(()=>setPhase((phase+1)%3),3200);});
  function stopTour(){clearInterval(tourTimer);tourTimer=null;q('#guided-tour').textContent='Play guided walkthrough →';}
  q('#guided-tour').addEventListener('click',()=>{if(tourTimer){stopTour();return;}stopCycle();if(paused)setMotion(false);const sequence=[[0,0],[2,0],[2,1],[4,1],[5,2],[0,2]];let step=0;const next=()=>{setScenario(sequence[step][0]);setPhase(sequence[step][1]);q('#guided-tour').textContent=`Ⅱ Walkthrough ${step+1} / ${sequence.length}`;step++;if(step===sequence.length){clearInterval(tourTimer);tourTimer=null;q('#guided-tour').textContent='Replay guided walkthrough →';}};next();tourTimer=setInterval(next,4300);});
  q('#snapshot').addEventListener('click',()=>{const a=document.createElement('a');a.download=`PhaseFlow_${scenarios[liveScenario][0]}_${['stable','constrained','recovery'][phase]}_illustration.png`;a.href=canvas.toDataURL('image/png');a.click();});
  canvas.addEventListener('pointermove',e=>{const r=canvas.getBoundingClientRect();pointer.x=(e.clientX-r.left)/r.width-.5;pointer.y=(e.clientY-r.top)/r.height-.5;});canvas.addEventListener('pointerleave',()=>{pointer={x:0,y:0};});
  canvas.addEventListener('click',e=>{const r=canvas.getBoundingClientRect(),x=e.clientX-r.left,y=e.clientY-r.top;let best=-1,dist=40;renderNodes.forEach((n,i)=>{const d=Math.hypot(n.x-x,n.y-y);if(d<dist){best=i;dist=d;}});if(best>=0)inspect(best);});
  const inspectButtons=document.createElement('div');inspectButtons.className='node-accessible';inspectButtons.innerHTML='<button data-inspect="0">Inspect Ryu controller</button><button data-inspect="1">Inspect Open vSwitch</button><button data-inspect="4">Inspect host</button>';q('.network-canvas-wrap').append(inspectButtons);qa('[data-inspect]').forEach(b=>b.addEventListener('click',()=>inspect(Number(b.dataset.inspect))));
  function inspect(index){inspectIndex=index;const n=renderNodes[index];if(!n)return;q('#node-inspector span').textContent=n.label;q('#node-inspector strong').textContent=n.type==='controller'?'Ryu coordinates switch behavior through OpenFlow 1.3.':n.type==='switch'?'Open vSwitch forwards packets and exposes flow-table counters.':'A virtual Mininet endpoint sends or receives a controlled workload.';}
  function point(a,b,t){return{x:a.x+(b.x-a.x)*t,y:a.y+(b.y-a.y)*t};}
  function device(n,index,t){const c=ctx,s=cw<500?12:17;const hover=index===inspectIndex;c.save();c.translate(n.x,n.y);c.strokeStyle=hover?'#fff':n.type==='controller'?'#bcbcb7':'#777';c.lineWidth=hover?1.6:1;c.fillStyle=n.type==='controller'?'#343430':'#1d1d1b';c.beginPath();c.moveTo(0,-s);c.lineTo(s*1.4,-s*.3);c.lineTo(0,s*.4);c.lineTo(-s*1.4,-s*.3);c.closePath();c.fill();c.stroke();c.fillStyle='#161615';c.beginPath();c.moveTo(-s*1.4,-s*.3);c.lineTo(0,s*.4);c.lineTo(0,s*1.3);c.lineTo(-s*1.4,s*.6);c.closePath();c.fill();c.stroke();c.fillStyle='#262623';c.beginPath();c.moveTo(0,s*.4);c.lineTo(s*1.4,-s*.3);c.lineTo(s*1.4,s*.6);c.lineTo(0,s*1.3);c.closePath();c.fill();c.stroke();for(let i=0;i<3;i++){c.fillStyle=n.type==='controller'?'#ecece5':'#a6a6a0';c.fillRect(5+i*4,s*.5-i*2,2,2);}if(hover){c.strokeStyle='#eee';c.setLineDash([2,4]);c.beginPath();c.ellipse(0,s*1.5,s*2.6,s*.8,0,0,Math.PI*2);c.stroke();c.setLineDash([]);}c.textAlign='center';c.fillStyle=n.type==='controller'?'#d5d5cf':'#888';c.font=(cw<500?'6':'8')+'px monospace';c.fillText(n.label,0,s*2.2);c.restore();}
  drawGlobe=function(t){if(!cw||!ch||activeRoute!=='home')return;const c=ctx,w=cw,h=ch;c.fillStyle='#0c0c0c';c.fillRect(0,0,w,h);const mobile=w<500,shiftX=paused?0:pointer.x*8,shiftY=paused?0:pointer.y*5;const cx=w*.52+shiftX,cy=h*.58+shiftY,sx=w*(mobile?.32:.34),sy=h*.26;
    c.strokeStyle='#232322';c.lineWidth=.6;for(let j=-7;j<=7;j++){c.beginPath();c.moveTo(cx-sx*1.3+j*25,cy-sy*.8);c.lineTo(cx+sx*1.3+j*25,cy+sy*.8);c.stroke();c.beginPath();c.moveTo(cx-sx*1.3+j*25,cy+sy*.8);c.lineTo(cx+sx*1.3+j*25,cy-sy*.8);c.stroke();}
    const coords=[[0,-1.2,'RYU / CONTROL','controller'],[-.52,-.22,'OVS 01','switch'],[.52,-.22,'OVS 02','switch'],[0,.64,'OVS 03','switch'],[-1,-.72,'HOST 01','host'],[.96,-.72,'HOST 02','host'],[-1,.65,'HOST 03','host'],[1,.65,'HOST 04','host'],[-.53,1.2,'HOST 05','host'],[.53,1.2,'SERVICE','host']];
    renderNodes=coords.map(([x,y,label,type])=>({x:cx+x*sx,y:cy+y*sy,label,type}));const n=renderNodes;const edges=topology==='star'?[[1,2],[1,3],[1,4],[2,5],[1,6],[2,7],[3,8],[3,9]]:[[1,2],[2,3],[1,4],[2,5],[1,6],[2,7],[3,8],[3,9]];
    for(const i of [1,2,3]){c.strokeStyle='#4c4c47';c.setLineDash([3,5]);c.beginPath();c.moveTo(n[0].x,n[0].y+15);c.lineTo(n[i].x,n[i].y);c.stroke();}c.setLineDash([]);
    edges.forEach(([ai,bi],ei)=>{const a=n[ai],b=n[bi];c.strokeStyle=phase===1?'#48483e':'#494946';c.lineWidth=phase===1?1.6:1;c.beginPath();c.moveTo(a.x,a.y);c.lineTo(b.x,b.y);c.stroke();let count=liveScenario===3?7:liveScenario===1?(Math.sin(elapsed*.0015)>0?6:1):liveScenario===5?1:liveScenario===4?3:2;for(let j=0;j<count;j++){let u=(elapsed/(phase===1?4400:2300)+ei*.17+j/count)%1;if(liveScenario===4&&j%2)u=1-u;let p=point(a,b,u),tail=point(a,b,Math.max(0,u-.04));c.strokeStyle=j%2===0?'#e9e9dd':'#93938c';c.lineWidth=1.5;c.beginPath();c.moveTo(tail.x,tail.y);c.lineTo(p.x,p.y);c.stroke();c.fillStyle='#eeeee6';c.fillRect(p.x-1.3,p.y-1.3,2.6,2.6);}});
    if(liveScenario===2){for(let j=0;j<4;j++){const a=n[9],b={x:Math.min(w-24,a.x+w*.12),y:a.y-47+j*23};c.strokeStyle='#77776d';c.beginPath();c.moveTo(a.x,a.y);c.lineTo(b.x,b.y);c.stroke();const p=point(a,b,(elapsed/1600+j*.25)%1);c.fillStyle='#fff';c.fillRect(p.x-2,p.y-2,4,4);c.strokeRect(b.x-5,b.y-5,10,10);c.font='6px monospace';c.fillStyle='#999';c.fillText('P'+(j+1),b.x+9,b.y+2);}}
    n.forEach((node,i)=>device(node,i,t));if(phase===1){c.setLineDash([2,4]);c.strokeStyle='#78786b';c.beginPath();c.ellipse(cx,cy,w*.19,h*.15,.2,0,Math.PI*2);c.stroke();c.setLineDash([]);c.font='7px monospace';c.fillStyle='#aaa99d';c.fillText('CONSTRAINED LINKS',cx-w*.1,cy+h*.23);}
    c.textAlign='left';c.font='6px monospace';c.fillStyle='#5e5e59';c.fillText('LINE / STAR TOPOLOGY · ISOLATED TESTBED',20,h-36);
  };
  const paperNav=document.createElement('div');paperNav.className='research-extras';paperNav.innerHTML='<a href="#framework">Explore the methodology ↗</a><a href="#workloads">Inspect workload evidence ↗</a><a href="#downloads">Download the research packages ↓</a>';q('#research').prepend(paperNav);
  setScenario(0);setPhase(0);setMotion(paused);route();
})();
